// lib/api/src/rest/schema.rs:614-620 — M3's 400 message is emitted by THIS untagged enum when every alternative fails
#[derive(Debug, Serialize, Deserialize, JsonSchema)]
#[serde(untagged)]
#[serde(expecting = "Expected some form of vector, id, or a type of query")]
pub enum QueryInterface {
    Nearest(VectorInput),
    Query(Query),
}

