// lib/api/src/rest/schema.rs:833-844 — THE DEFECT: context carries serde(with) WITHOUT serde(default)
#[derive(Debug, Serialize, Deserialize, JsonSchema, Validate)]
pub struct DiscoverInput {
    /// Use this as the primary search objective
    #[validate(nested)]
    pub target: VectorInput,

    /// Search space will be constrained by these pairs of vectors
    #[validate(nested)]
    #[serde(with = "MaybeOneOrMany")]
    #[schemars(with = "MaybeOneOrMany<ContextPair>")]
    pub context: Option<Vec<ContextPair>>,
}

// lib/api/src/rest/schema.rs:755-761 — CONTRAST inside the same file: Prefetch.prefetch deliberately carries default+with, which is why prefetch omission parses fine
    #[validate(nested)]
    #[serde(default, with = "MaybeOneOrMany")]
    #[schemars(with = "MaybeOneOrMany<Prefetch>")]
    pub prefetch: Option<Vec<Prefetch>>,

// serde_derive-1.0.228/src/de.rs:789-801 (exact version pinned in Cargo.lock) — with-deserializer + no default => hard missing-field error; the Option->None tolerance applies only WITHOUT deserialize_with
    match field.attrs.deserialize_with() {
        None => {
